import re
from decimal import Decimal, ROUND_HALF_UP

_NUM = r"(?:\d+(?:\.\d+)?|\.\d+)"

_UNITS = {}
for _names, _secs in [
    (("s", "sec", "secs", "second", "seconds"), 1),
    (("m", "min", "mins", "minute", "minutes"), 60),
    (("h", "hr", "hrs", "hour", "hours"), 3600),
    (("d", "day", "days"), 86400),
    (("w", "wk", "wks", "week", "weeks"), 604800),
]:
    for _n in _names:
        _UNITS[_n] = _secs

_COMPONENTS_RE = re.compile(rf"(?:{_NUM}\s*[A-Za-z]+\s*)+")
_COMPONENT_RE = re.compile(rf"({_NUM})\s*([A-Za-z]+)")
_ISO_RE = re.compile(
    rf"P(?:({_NUM})W)?(?:({_NUM})D)?"
    rf"(T(?:({_NUM})H)?(?:({_NUM})M)?(?:({_NUM})S)?)?",
    re.IGNORECASE,
)
_CLOCK_RE = re.compile(r"(\d+):(\d+)(?::(\d+(?:\.\d+)?))?")


def _round(total: Decimal) -> int:
    return int(total.quantize(Decimal(1), rounding=ROUND_HALF_UP))


def _parse_iso(text: str) -> int:
    m = _ISO_RE.fullmatch(text)
    if not m:
        raise ValueError(f"invalid ISO 8601 duration: {text!r}")
    weeks, days, t_part, hours, minutes, seconds = m.group(1, 2, 3, 4, 5, 6)
    if weeks is None and days is None and t_part is None:
        raise ValueError(f"invalid ISO 8601 duration: {text!r}")
    if t_part is not None and hours is None and minutes is None and seconds is None:
        raise ValueError(f"invalid ISO 8601 duration: {text!r}")
    total = Decimal(0)
    for value, mult in [(weeks, 604800), (days, 86400), (hours, 3600),
                        (minutes, 60), (seconds, 1)]:
        if value is not None:
            total += Decimal(value) * mult
    return _round(total)


def _parse_clock(text: str) -> int:
    m = _CLOCK_RE.fullmatch(text)
    if not m:
        raise ValueError(f"invalid clock duration: {text!r}")
    a, b, c = m.groups()
    if c is None:
        return int(a) * 60 + int(b)
    return int(a) * 3600 + int(b) * 60 + _round(Decimal(c))


def _parse_components(text: str) -> int:
    total = Decimal(0)
    for num, unit in _COMPONENT_RE.findall(text):
        mult = _UNITS.get(unit.lower())
        if mult is None:
            raise ValueError(f"unknown unit: {unit!r}")
        total += Decimal(num) * mult
    return _round(total)


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    if s.isdigit() and s.isascii():
        return int(s)
    if s[0] in "Pp":
        return _parse_iso(s)
    if ":" in s:
        return _parse_clock(s)
    if _COMPONENTS_RE.fullmatch(s):
        return _parse_components(s)
    raise ValueError(f"invalid duration: {text!r}")

